// Read first worksheet from a standard, unencrypted XLSX ZIP locally.
export async function readXlsx(buffer){
const v=new DataView(buffer),bytes=new Uint8Array(buffer),files={};let end=bytes.length-22;while(end>=Math.max(0,bytes.length-65557)&&v.getUint32(end,true)!==0x06054b50)end--;if(end<0)throw Error('Некорректный XLSX.');let offset=v.getUint32(end+16,true),count=v.getUint16(end+10,true),decoder=new TextDecoder();for(let i=0;i<count;i++){if(v.getUint32(offset,true)!==0x02014b50)throw Error('Повреждён ZIP.');let method=v.getUint16(offset+10,true),size=v.getUint32(offset+20,true),nameLen=v.getUint16(offset+28,true),extraLen=v.getUint16(offset+30,true),commentLen=v.getUint16(offset+32,true),local=v.getUint32(offset+42,true),name=decoder.decode(bytes.slice(offset+46,offset+46+nameLen));let start=local+30+v.getUint16(local+26,true)+v.getUint16(local+28,true);if(/xl\/(sharedStrings.xml|worksheets\/sheet1.xml)$/.test(name)){let data=bytes.slice(start,start+size);if(method===8){try{data=new Uint8Array(await new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer());}catch{throw Error('Браузер не поддерживает распаковку XLSX. Сохраните таблицу как CSV.');}}else if(method!==0)throw Error('Неподдерживаемое сжатие XLSX.');files[name]=decoder.decode(data);}offset+=46+nameLen+extraLen+commentLen;}
const parser=new DOMParser(),shared=files['xl/sharedStrings.xml']?[...parser.parseFromString(files['xl/sharedStrings.xml'],'text/xml').querySelectorAll('si')].map(si=>[...si.querySelectorAll('t')].map(t=>t.textContent).join('')):[];if(!files['xl/worksheets/sheet1.xml'])throw Error('Не найден первый лист.');return[...parser.parseFromString(files['xl/worksheets/sheet1.xml'],'text/xml').querySelectorAll('row')].map(row=>{let cell=row.querySelector('c');if(!cell)return'';let value=cell.querySelector('v')?.textContent||cell.querySelector('t')?.textContent||'';return cell.getAttribute('t')==='s'?shared[+value]:value;}).filter(w=>w&& !/^(слово|word|слова)$/i.test(w));}
